/** Accepts only the ephemeral IPv4 loopback callback generated by the official CLI. */
export function parseCliCallback(fragment: string): { callback: string; state: string } | null {
  try {
    const parameters = new URLSearchParams(fragment.replace(/^#/, ''));
    const callback = new URL(parameters.get('callback') || '');
    const state = parameters.get('state') || '';
    if (
      callback.protocol !== 'http:' ||
      callback.hostname !== '127.0.0.1' ||
      !callback.port ||
      Number(callback.port) < 1024 ||
      callback.pathname !== '/callback' ||
      callback.username ||
      callback.password ||
      callback.search ||
      callback.hash ||
      !/^[a-f0-9]{64}$/.test(state)
    )
      return null;
    return { callback: callback.href, state };
  } catch {
    return null;
  }
}
